INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (17, 1, 'theory', 'Quiz: why virtualization and the Popek and Goldberg conditions');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (17, 1, 0, 'Which of the following is NOT a benefit of virtualization?', '["Isolation: a crash of one machine does not break its neighbors", "Snapshots and moving running machines between servers", "Speeding up each individual program compared with running on bare metal", "Denser use of a server by several machines"]', 2, 'Virtualization adds a layer between the program and the hardware, so it can never be faster than bare metal. Its benefits are isolation, density, and manageability.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (17, 1, 1, 'Which Popek and Goldberg property requires that the vast majority of guest instructions go straight to the processor?', '["Equivalence", "Resource control", "Isolation", "Efficiency"]', 3, 'Equivalence means the guest behaves as on a real computer, resource control means the monitor controls everything it hands out, and efficiency means almost all instructions run without the monitor''s involvement.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (17, 1, 2, 'What does the Popek and Goldberg theorem say?', '["A monitor is simple to build if every sensitive instruction is also privileged", "Every privileged instruction must be sensitive", "The guest must be modified for the hypervisor", "A virtual machine monitor cannot be built without hardware support"]', 0, 'Then every dangerous guest instruction causes a trap, and the processor itself hands control to the monitor. If there are sensitive instructions that are not privileged, the scheme breaks.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (17, 1, 3, 'How does emulation differ from virtualization?', '["Emulation is always faster because it does not use the host processor", "Emulation executes guest instructions in software, so the guest can be of another architecture but runs slowly; virtualization runs them on the real processor", "Emulation can isolate guests, while virtualization cannot", "There is no difference; they are two names for the same technology"]', 1, 'QEMU in translation mode emulates a foreign processor several times to tens of times slower. With virtualization the guest has the same architecture, and its instructions go straight to the hardware.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (17, 1, 4, 'How is KVM built in terms of hypervisor types?', '["It is a type 2 hypervisor: an ordinary program on top of the host OS", "It is a container system with no hypervisor", "A hybrid: the Linux kernel itself becomes the hypervisor, and a virtual machine is a QEMU process", "It is a separate type 1 micro-OS with no host system"]', 2, 'KVM is a kernel module: the host stays an ordinary Linux but gains the right to run guests directly on the processor. This blurs the line between type 1 and type 2.');
